import './scene.js';
let audio,master,wave='sine',ambientTimer=null;const frequencies=[261.63,293.66,329.63,349.23,392,440,493.88];const keys=['A','S','D','F','G','H','J'];const names=['Do','Re','Mi','Fa','Sol','La','Si'];
async function enableAudio(){audio??=new(window.AudioContext||window.webkitAudioContext)();if(!master){master=audio.createGain();master.gain.value=.3;master.connect(audio.destination)}if(audio.state==='suspended')await audio.resume();}
function tone(f,duration=.5,type=wave,delay=0,volume=.5){if(!audio||audio.state!=='running')return;const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+delay;o.type=type;o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(master);o.start(t);o.stop(t+duration+.02);o.onended=()=>{o.disconnect();g.disconnect()};}
const piano=document.querySelector('#piano');function fillPiano(el){el.innerHTML=keys.map((k,i)=>`<button class="piano-key ${[0,1,3,4,5].includes(i)?'black':''}" data-note="${i}" aria-label="${names[i]}，键盘 ${k}"><span>${k}</span></button>`).join('');}fillPiano(piano);
async function playNote(i){await enableAudio();tone(frequencies[i],1.25,wave,0,.6);document.querySelectorAll(`[data-note="${i}"]`).forEach(b=>{b.classList.add('active');setTimeout(()=>b.classList.remove('active'),220)});document.querySelector('#note-display').textContent=`♪ ${names[i]} · 每个音都算数`;}
document.addEventListener('pointerdown',e=>{const k=e.target.closest('[data-note]');if(k){e.preventDefault();playNote(+k.dataset.note)}});
document.addEventListener('click',e=>{const k=e.target.closest('[data-note]');if(k&&e.detail===0)playNote(+k.dataset.note)});
document.querySelector('#wave-toggle').addEventListener('click',e=>{wave=wave==='sine'?'triangle':'sine';e.currentTarget.innerHTML=`音色：${wave==='sine'?'柔和':'明亮'} <span>↻</span>`});
document.querySelector('.sound-toggle').addEventListener('click',async e=>{const b=e.currentTarget;await enableAudio();if(ambientTimer){clearInterval(ambientTimer);ambientTimer=null;b.setAttribute('aria-pressed','false');b.querySelector('span').textContent='声音关闭';b.title='开启环境音乐'}else{let step=0;const melody=[0,2,4,6,4,2,1,4];const tick=()=>{tone(frequencies[melody[step%8]]/2,1.7,'sine',0,.17);if(step%4===0)[130.81,164.81,196].forEach(f=>tone(f,3,'sine',0,.07));step++};tick();ambientTimer=setInterval(tick,650);b.setAttribute('aria-pressed','true');b.querySelector('span').textContent='声音开启';b.title='关闭环境音乐'}});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));document.querySelectorAll('[data-category]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter)}));
const dialog=document.querySelector('#game-dialog'),content=document.querySelector('#game-content');let beatTimer,finishTimer,beatRunning=false,beatStart=0,beatHits=[],score=0,count=0,previousFocus;function stopBeat(){clearInterval(beatTimer);clearTimeout(finishTimer);beatRunning=false;}
function closeGame(){stopBeat();dialog.close();previousFocus?.focus();}document.querySelector('.dialog-close').addEventListener('click',closeGame);dialog.addEventListener('cancel',()=>{stopBeat()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeGame()}});dialog.addEventListener('close',stopBeat);
function openGame(game){previousFocus=document.activeElement;stopBeat();if(game==='synth'){document.querySelector('#dialog-title').textContent='口袋合成器';content.innerHTML='<p>让手指跟着心情走。点琴键或按 A S D F G H J，自由演奏属于你的旋律。</p><div class="piano"></div><p>七个音，没有规则。试试：A D G D，S F H F。</p>';fillPiano(content.querySelector('.piano'));}else{document.querySelector('#dialog-title').textContent='节拍弹跳';content.innerHTML='<p>先听一拍，再跟着节奏点击「打节拍」或按空格。每拍 750 毫秒，挑战 16 拍。</p><div class="beat-display"><div class="beat-circle">♪</div></div><div class="beat-status">命中 <b id="hit-count">0</b> / 16 · 得分 <b id="score">0</b></div><p class="game-result" aria-live="polite">准备好，让节奏开始。</p><div class="beat-controls"><button class="button primary" id="beat-start">开始挑战 ↗</button><button class="button tap-button" id="beat-tap" disabled>打节拍 / 空格</button></div>';content.querySelector('#beat-start').addEventListener('click',startBeat);content.querySelector('#beat-tap').addEventListener('click',tapBeat);}dialog.showModal();}
document.querySelectorAll('[data-game]').forEach(b=>b.addEventListener('click',()=>openGame(b.dataset.game)));document.querySelector('#random-game').addEventListener('click',()=>{const n=Math.floor(Math.random()*3);if(n===0)location.href='symphony/';else openGame(n===1?'rhythm':'synth')});
async function startBeat(){await enableAudio();stopBeat();score=0;count=0;beatHits=[];beatRunning=true;beatStart=performance.now()+750;content.querySelector('#score').textContent='0';content.querySelector('#hit-count').textContent='0';content.querySelector('#beat-start').disabled=true;content.querySelector('#beat-tap').disabled=false;content.querySelector('.game-result').textContent='先听一拍，再跟上！';let n=0;const tick=()=>{if(!beatRunning)return;tone(n%4===0?880:660,.12,'sine',0,.5);const c=content.querySelector('.beat-circle');c.classList.add('pulse');c.textContent=n===0?'♪':Math.min(n,16);setTimeout(()=>c.classList.remove('pulse'),120);n++;if(n>16){clearInterval(beatTimer);finishTimer=setTimeout(finishBeat,360)}};tick();beatTimer=setInterval(tick,750);}
function tapBeat(){if(!beatRunning)return;const elapsed=performance.now()-beatStart,beat=Math.round(elapsed/750),delta=Math.abs(elapsed-beat*750);if(beat<0||beat>15||delta>300){content.querySelector('.game-result').textContent='听一听，等下一拍。';return}if(beatHits.includes(beat))return;beatHits.push(beat);count++;const earned=delta<85?100:delta<160?70:40;score+=earned;content.querySelector('#score').textContent=score;content.querySelector('#hit-count').textContent=count;content.querySelector('.game-result').textContent=earned===100?'PERFECT · 踩得正好！':earned===70?'GOOD · 感觉来了！':'跟上啦，再稳一点！';tone(261.63,.13,'triangle',0,.25);}
function finishBeat(){stopBeat();content.querySelector('.game-result').textContent=`挑战完成！${score>=1200?'节奏大师，就是你。':score>=700?'不错，再来一局找找手感？':'慢慢来，快乐比得分重要。'} ${score} 分`;content.querySelector('#beat-start').disabled=false;content.querySelector('#beat-start').textContent='再来一局 ↗';content.querySelector('#beat-tap').disabled=true;}
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.code==='Space'&&dialog.open&&content.querySelector('#beat-tap')){e.preventDefault();tapBeat();return;}const i=keys.indexOf(e.key.toUpperCase());if(i>=0&&(!dialog.open||content.querySelector('.piano'))){e.preventDefault();playNote(i)}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&beatRunning){stopBeat();content.querySelector('.game-result').textContent='挑战已暂停，请重新开始。';content.querySelector('#beat-start').disabled=false;content.querySelector('#beat-tap').disabled=true;}});
